<script setup lang="ts">import { getColorChannelConfig,getColorChannelValue } from '@fex-design/core/color-picker/channels';import { valueToPosition } from '@fex-design/core/color-picker/coordinates';import { colorPickerChannelThumbClassName } from '@fex-design/styles/color-picker';import { cn } from '@fex/utils';import { computed,useAttrs } from 'vue';import { useColorChannel,useColorPicker } from './context';defineOptions({inheritAttrs:false});const attrs=useAttrs(),picker=useColorPicker(),channel=useColorChannel();const style=computed(()=>{const value=picker.snapshot.value.value;if(!value)return{display:'none'};const c=getColorChannelConfig(channel.value),p=valueToPosition(getColorChannelValue(value,channel.value),c.min,c.max);return{left:`clamp(6px, ${p*100}%, calc(100% - 6px))`,top:'50%',transform:'translate(-50%,-50%)'}})</script><template><span v-bind="attrs" :class="cn(colorPickerChannelThumbClassName,attrs.class as string|undefined)" :style="[style,attrs.style]" /></template>
